def apply_operator(ops, operands):
    result = operands[0]
    for i in range(len(ops)):
        if ops[i] == '+':
            result += operands[i + 1]
        elif ops[i] == '-':
            result -= operands[i + 1]
        elif ops[i] == '*':
            result *= operands[i + 1]
        elif ops[i] == '//':
            result //= operands[i + 1]
        elif ops[i] == '**':
            result **= operands[i + 1]
    return result

